    if len(summary.Learnings) != 0 {
        t.Errorf("Learnings should be empty, got %v", summary.Learnings)
    }
    if len(summary.FrictionPoints) != 0 {
        t.Errorf("FrictionPoints should be empty, got %v", summary.FrictionPoints)
    }
}
